      expect(req.headers.get('authorization')).toBe('Bearer test-key-us1');
      const body = req.json as { email_address: string; tags: Array<{ name: string }> };
      expect(body.email_address).toBe('customer@example.com');
      expect(body.tags).toEqual([{ name: 'pro-plan', status: 'active' }]);
      return jsonResponse({ id: 'member-456', email_address: 'customer@example.com', tags: [{ id: 1, name: 'pro-plan', status: 'active' }] }, 200);
    });

    const payload: StripeWebhookPayload = {
      id: 'evt_test',
      type: 'checkout.session.completed',
      data: {
        object: {
          id: 'cs_test',
          customer: 'cus_test',
          customer_details: { email: 'customer@example.com' },
          metadata: { plan_name: 'pro-plan' },
          subscription: 'sub_test',
          payment_status: 'paid',
          status: 'complete'
        }
      }
    };

    const result = await handle(payload, { ...baseConfig, fetch });
    expect(result.mailchimpMemberId).toBe('member-456');
    expect(result.email).toBe('customer@example.com');
    expect(result.tags).toEqual(['pro-plan']);
    expect(calls).toHaveLength(1);
